import {
  type ReactNode,
  useState,
  useEffect,
  useCallback,
  useRef,
  createContext,
  useContext,
} from 'react';
import { Button } from '../atoms/Button';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

/* ---- Context ---- */

type AlertDialogContextValue = {
  open: boolean;
  setOpen: (v: boolean) => void;
};

// Debe coincidir con la animacion de salida de alert-dialog--exiting en el CSS.
const EXIT_DURATION_MS = 200;

const FOCUSABLE = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(',');

const AlertDialogContext = createContext<AlertDialogContextValue | null>(null);

function useAlertDialog() {
  const ctx = useContext(AlertDialogContext);
  if (!ctx) throw new Error('AlertDialog components must be used within <AlertDialog>');
  return ctx;
}

/* ---- Root ---- */

export type AlertDialogProps = {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: ReactNode;
};

export function AlertDialog({ open: controlledOpen, onOpenChange, children }: AlertDialogProps) {
  const [internalOpen, setInternalOpen] = useState(false);
  const open = controlledOpen ?? internalOpen;

  const setOpen = useCallback(
    (v: boolean) => {
      onOpenChange ? onOpenChange(v) : setInternalOpen(v);
    },
    [onOpenChange],
  );

  return (
    <AlertDialogContext.Provider value={{ open, setOpen }}>
      {children}
    </AlertDialogContext.Provider>
  );
}

/* ---- Trigger ---- */

export function AlertDialogTrigger({ children, className }: { children: ReactNode; className?: string }) {
  const { setOpen } = useAlertDialog();
  return (
    <div
      role="button"
      tabIndex={0}
      className={className}
      style={{ display: 'inline-flex' }}
      onClick={() => setOpen(true)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setOpen(true); }
      }}
    >
      {children}
    </div>
  );
}

/* ---- Content ---- */

export type AlertDialogContentProps = {
  size?: 'default' | 'sm';
  children: ReactNode;
  className?: string;
};

export function AlertDialogContent({ size = 'default', children, className }: AlertDialogContentProps) {
  const { open, setOpen } = useAlertDialog();
  const [exiting, setExiting] = useState(false);
  const [mounted, setMounted] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  // `open` es lo unico que decide si el dialogo esta abierto. Si el consumidor lo
  // controla y veta el cierre, el contenido tiene que quedarse: desmontar desde
  // aqui lo dejaba cerrado para siempre, porque `open` ya nunca vuelve a cambiar.
  // `mounted` solo estira la vida en el DOM lo que dura la animacion de salida.
  useEffect(() => {
    if (open) {
      setMounted(true);
      setExiting(false);
      return;
    }
    if (!mounted) return;
    setExiting(true);
    const timer = setTimeout(() => {
      setMounted(false);
      setExiting(false);
    }, EXIT_DURATION_MS);
    return () => clearTimeout(timer);
  }, [open, mounted]);

  // Escape triggers cancel (closes)
  useEffect(() => {
    if (!mounted) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [mounted, setOpen]);

  // Scroll lock
  useEffect(() => {
    if (!mounted) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, [mounted]);

  // Al abrir, el foco entra al dialogo; al cerrar vuelve a quien lo abrio, que es
  // donde estaba el usuario antes de la interrupcion.
  useEffect(() => {
    if (!mounted) return;
    const opener = document.activeElement as HTMLElement | null;
    contentRef.current?.focus();
    return () => {
      if (opener && document.contains(opener)) opener.focus();
    };
  }, [mounted]);

  // Focus trap real: con aria-modal el lector de pantalla ya ignora el fondo, pero
  // el Tab del navegador no. En un alertdialog importa aun mas: es una decision
  // que el usuario tiene que resolver antes de seguir.
  useEffect(() => {
    if (!mounted) return;
    const node = contentRef.current;
    if (!node) return;

    const handler = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return;
      const focusables = Array.from(node.querySelectorAll<HTMLElement>(FOCUSABLE));
      if (focusables.length === 0) {
        e.preventDefault();
        node.focus();
        return;
      }
      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      const active = document.activeElement;
      const outside = !node.contains(active);

      if (e.shiftKey && (active === first || active === node || outside)) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && (active === last || outside)) {
        e.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [mounted]);

  if (!mounted) return null;

  return (
    <>
      <div className={cn('dialog__overlay', exiting && 'dialog__overlay--exiting')} aria-hidden="true" />
      <div
        ref={contentRef}
        role="alertdialog"
        aria-modal="true"
        tabIndex={-1}
        className={cn('alert-dialog', size === 'sm' && 'alert-dialog--sm', exiting && 'alert-dialog--exiting', className)}
      >
        {children}
      </div>
    </>
  );
}

/* ---- Header ---- */

export function AlertDialogHeader({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn('alert-dialog__header', className)}>{children}</div>;
}

/* ---- Media ---- */

export type AlertDialogMediaProps = {
  variant?: 'default' | 'destructive';
  children: ReactNode;
  className?: string;
};

export function AlertDialogMedia({ variant = 'default', children, className }: AlertDialogMediaProps) {
  return (
    <div className={cn('alert-dialog__media', variant === 'destructive' && 'alert-dialog__media--destructive', className)}>
      {children}
    </div>
  );
}

/* ---- Title ---- */

export function AlertDialogTitle({ children, className }: { children: ReactNode; className?: string }) {
  return <h2 className={cn('alert-dialog__title', className)}>{children}</h2>;
}

/* ---- Description ---- */

export function AlertDialogDescription({ children, className }: { children: ReactNode; className?: string }) {
  return <p className={cn('alert-dialog__description', className)}>{children}</p>;
}

/* ---- Footer ---- */

export function AlertDialogFooter({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn('alert-dialog__footer', className)}>{children}</div>;
}

/* ---- Cancel ---- */

export type AlertDialogCancelProps = {
  children?: ReactNode;
  className?: string;
};

export function AlertDialogCancel({ children = 'Cancel', className }: AlertDialogCancelProps) {
  const { setOpen } = useAlertDialog();
  return (
    <Button variant="secondary" size="m" className={className} onClick={() => setOpen(false)}>
      {children}
    </Button>
  );
}

/* ---- Action ---- */

export type AlertDialogActionProps = {
  variant?: 'primary' | 'destructive-primary';
  onAction?: () => void;
  children?: ReactNode;
  className?: string;
};

export function AlertDialogAction({
  variant = 'primary',
  onAction,
  children = 'Continue',
  className,
}: AlertDialogActionProps) {
  const { setOpen } = useAlertDialog();
  return (
    <Button
      variant={variant}
      size="m"
      className={className}
      onClick={() => {
        onAction?.();
        setOpen(false);
      }}
    >
      {children}
    </Button>
  );
}

/* -------------------------------------------------------------------------
   Alert Dialog

   Non-dismissible confirmation modal. No overlay close, no X button.
   Requires explicit Cancel or Action to close.

   Sizes: default (512px), sm (400px)
   Parts: .alert-dialog, .alert-dialog__header, .alert-dialog__media,
          .alert-dialog__title, .alert-dialog__description,
          .alert-dialog__footer
   ------------------------------------------------------------------------- */

/* ---- Content ---- */

.alert-dialog {
  position: fixed;
  z-index: var(--z-index-50);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: calc(100% - var(--spacing-8, 32px));
  max-width: 512px;
  display: flex;
  flex-direction: column;
  border: var(--stroke-hairline) solid var(--border);
  border-radius: var(--radius-xl);
  background-color: var(--popover);
  color: var(--popover-foreground);
  box-shadow: var(--shadow-xl);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  animation: alert-dialog-in var(--duration-300) var(--easing-out);
}

.alert-dialog--sm {
  max-width: 400px;
}

.alert-dialog--exiting {
  animation: alert-dialog-out var(--duration-200) var(--easing-in) forwards;
}

@keyframes alert-dialog-in {
  from {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}

@keyframes alert-dialog-out {
  from {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
}

/* ---- Header ---- */

.alert-dialog__header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-3, 12px);
  padding: var(--spacing-6, 24px);
  padding-bottom: 0;
  text-align: center;
}

/* ---- Media ---- */

.alert-dialog__media {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--spacing-12, 48px);
  height: var(--spacing-12, 48px);
  border-radius: var(--radius-full);
  background-color: var(--muted);
  color: var(--muted-foreground);
  padding: var(--spacing-3, 12px);
}

.alert-dialog__media--destructive {
  background-color: var(--destructive);
  color: var(--destructive-foreground);
}

.alert-dialog__media svg {
  width: 100%;
  height: 100%;
}

/* ---- Title ---- */

.alert-dialog__title {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  line-height: var(--line-height-lg);
  color: var(--foreground);
  margin: 0;
}

/* ---- Description ---- */

.alert-dialog__description {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
  color: var(--muted-foreground);
  margin: 0;
}

/* ---- Footer ---- */

.alert-dialog__footer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-3, 12px);
  padding: var(--spacing-6, 24px);
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .alert-dialog,
  .alert-dialog--exiting {
    animation-duration: 0ms;
  }
}

